kill 428822 2>/dev/null; cat > /root/contamcal-irt-calibration/stan_models/vanilla_2pl_noll.stan << 'STANEOF'
// Vanilla 2PL IRT (no gamma, no log_lik for speed)
data {
  int<lower=1> N_models;
  int<lower=1> N_items;
  array[N_models, N_items] int<lower=0, upper=1> y;
}
parameters {
  vector[N_models] theta;
  vector<lower=0>[N_items] a;
  vector[N_items] b;
}
model {
  theta ~ std_normal();
  a ~ lognormal(0, 0.5);
  b ~ std_normal();
  for (i in 1:N_models)
    for (j in 1:N_items)
      y[i, j] ~ bernoulli_logit(a[j] * (theta[i] - b[j]));
}
generated quantities {
  array[N_models] real calibrated_score;
  for (i in 1:N_models) {
    real total = 0.0;
    for (j in 1:N_items)
      total += inv_logit(a[j] * (theta[i] - b[j]));
    calibrated_score[i] = total / N_items;
  }
}
STANEOF
echo "Stan model written"

